  var C = root.LotteryCore, LEGACY_MARKETS = ['新澳','香港','老澳','老澳门'];
  var state, pending = null, revision = 0, lastPreview = null, inboxPreview = null, viewCache = [], viewSearchTextCache = null, playStatsCache = [], sourceGroupsCache = [];
  var inspectedAdmissions = [], inspectedCharacters = 0;
  var recordEncodings = new WeakMap();
