      entries.push(st?freezeState(Object.assign({},projected,{settlement:null})):projected);
      projected.items.forEach(function(it){var key=scope+'|'+it.selection[0];balances[key]=(balances[key]||0)+it.stakeCents*adjustmentSign(r);assert(Number.isSafeInteger(balances[key]),'手动调整合计超出安全范围');});
