    if(s.declarantAliases!==undefined){assert(isObject(s.declarantAliases)&&Object.keys(s.declarantAliases).length<=10000,'申报人昵称设置无效');Object.keys(s.declarantAliases).forEach(function(alias){var owner=s.declarantAliases[alias];assert(alias.trim()&&alias.length<=40&&typeof owner==='string'&&owner.trim()&&owner.length<=40&&['__proto__','constructor','prototype'].indexOf(alias)<0,'申报人昵称归属无效');});}
    if(s.drawImpactScopes!==undefined){assert(isObject(s.drawImpactScopes),'开奖影响设置无效');Object.keys(s.drawImpactScopes).forEach(function(type){assert(s.qss&&Object.prototype.hasOwnProperty.call(s.qss.normalOdds,type)&&['regular','all'].indexOf(s.drawImpactScopes[type])>=0,'开奖影响范围无效');});}
    if(s.declarantDrawImpact!==undefined){assert(isObject(s.declarantDrawImpact),'申报人开奖影响设置无效');Object.keys(s.declarantDrawImpact).forEach(function(name){assert(typeof s.declarantDrawImpact[name]==='boolean','申报人开奖影响开关无效');});}
    if(s.pricingProfiles!==undefined){assert(isObject(s.pricingProfiles)&&Object.keys(s.pricingProfiles).length<=1000,'赔率配置组无效');Object.keys(s.pricingProfiles).forEach(function(name){assert(name.trim()&&name.length<=40&&isObject(s.pricingProfiles[name]),'赔率配置组格式无效');Object.keys(s.pricingProfiles[name]).forEach(function(type){var value=s.pricingProfiles[name][type];assert(s.qss&&Object.prototype.hasOwnProperty.call(s.qss.normalOdds,type)&&typeof value==='number'&&isFinite(value)&&value>=0&&value<=1000000,'赔率配置组数值无效');});});}
    if(s.declarantMultiPricing!==undefined){assert(isObject(s.declarantMultiPricing),'多赔率设置无效');Object.keys(s.declarantMultiPricing).forEach(function(name){var v=s.declarantMultiPricing[name];assert(isObject(v)&&typeof v.enabled==='boolean'&&Array.isArray(v.allowed)&&v.allowed.length>0,'多赔率选择无效');v.allowed.forEach(function(k){assert(k===''||s.pricingProfiles&&Object.prototype.hasOwnProperty.call(s.pricingProfiles,k),'赔率配置不存在');});});}
