        sumRows(combined.totals.byKind,totals.byKind,'kind',['totalCents','unitCount']);
        sumRows(combined.totals.byPerson,totals.byPerson,'person',['totalCents','count']);
        sumFields(combined.plays.totals,plays.totals,playFields);
        sumRows(combined.plays.rows,plays.rows,'kind',playFields);
        sumRows(combined.plays.pingxiaoZodiacs,plays.pingxiaoZodiacs,'zodiac',['totalCents','unitCount']);
        sumRows(combined.plays.texiaoZodiacs,plays.texiaoZodiacs,'zodiac',['totalCents','unitCount']);
        sumRows(combined.plays.pingweiTails,plays.pingweiTails,'tail',['totalCents','unitCount']);
