      if(!remaining||remaining.error||!original||original.error){group.riskExposure=clone(group.exposure);group.riskExposure.available=false;group.riskExposure.errors=[remaining&&remaining.error||original&&original.error||'总账本风控汇总失败'];return;}
      var plan=root.QsRisk.plan(remaining,{mode:'percent',value:100}),off=original.totalStakeCents-remaining.totalStakeCents;
      group.panelTotals=clone(group.totals);group.panelTotals.totalCents-=off;group.panelTotals.pendingCents-=off;
      group.riskExposure={market:group.market,available:true,errors:[],temaStakeCents:remaining.totalStakeCents,otherPendingCents:group.exposure.otherPendingCents,rebateCents:plan.rebateCents,
        bestNetCents:plan.bestNetCents,worstNetCents:plan.worstNetCents,maxProfitCents:Math.max(0,plan.bestNetCents),maxLossCents:Math.max(0,-plan.worstNetCents),rows:plan.rows.map(function(row){return {number:row.number,stakeCents:row.stakeCents,returnCents:remaining.totalStakeCents-plan.rebateCents-row.netCents,netCents:row.netCents};})};
