    var existing=journal.entries.find(function(e){return e.id===(action==='riskCommit'?a.token:a.id)&&e.market===a.market;});
    if(action==='riskCommit'&&existing){assert(a.confirm===true,'请确认抛单');return {result:result(existing)};}
