      stats.rows.forEach(function(row){assert(row.kind!=='tema','玩法导出不能包含特码');row.label=root.QSSRules.isKind(row.kind)?root.QSSRules.kindLabel(row.kind):C.kindLabel(row.kind);if(row.kind.indexOf('wisdom:')===0||row.totalCents>0)lines.push((row.kind.indexOf('wisdom:')===0?'':'历史 · ')+row.label+'下注额：'+displayMoney(row.totalCents)+'元');});
      lines.push('','平特十二生肖：');stats.pingxiaoZodiacs.forEach(function(row){lines.push(row.zodiac+'：'+displayMoney(row.totalCents)+'元');});
      lines.push('','特肖十二生肖：');stats.texiaoZodiacs.forEach(function(row){lines.push('特肖'+row.zodiac+'：'+displayMoney(row.totalCents)+'元');});
